def comps4(A):
    seen=set(); out=[]
    H,W=A.shape
    for i in range(H):
        for j in range(W):
            if A[i,j]!=6 and (i,j) not in seen:
                col=int(A[i,j]); stack=[(i,j)]; seen.add((i,j)); cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((-1,0),(1,0),(0,-1),(0,1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and (ny,nx) not in seen and A[ny,nx]==col:
                            seen.add((ny,nx)); stack.append((ny,nx))
                out.append((col,cells))
    return out
def norm(cells):
    ys=[y for y,_ in cells]; xs=[x for _,x in cells]
    my,mx=min(ys),min(xs)
    return frozenset((y-my,x-mx) for y,x in cells)
def transforms(cells):
    s=norm(cells)
    res=set()
    cur=s
    for _ in range(4):
        cur=frozenset((c,-r) for r,c in cur)  # rot90
        n=norm(list(cur))
        res.add(n)
        res.add(frozenset((r,-c) for r,c in n))  # mirror
        res.add(frozenset(norm(list(frozenset((r,-c) for r,c in n)))))
    res.add(s)
    return res
