def rot(cells):
    # rotations
    def nrm(cs):
        ys=[c[0] for c in cs]; xs=[c[1] for c in cs]
        return tuple(sorted((y-min(ys),x-min(xs)) for y,x in cs))
    out=[]; cur=list(cells)
    for _ in range(4):
        out.append(nrm(cur))
        cur=[(x,-y) for y,x in cur]
    return min(out)
def reflkey(cells):
    def nrm(cs):
        ys=[c[0] for c in cs]; xs=[c[1] for c in cs]
        return tuple(sorted((y-min(ys),x-min(xs)) for y,x in cs))
    m=[(y,-x) for y,x in cells]
    return min(rot(cells), rot(m))

